const root=document.querySelector('.mc-guide');
const groups=[...root.querySelectorAll('[data-tabs]')].map(group=>{const nav=group.querySelector('[role=tablist]');const tabs=[...nav.querySelectorAll('[role=tab]')];return{group,tabs};});
function activate(group,tab){group.tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.dataset.target).hidden=!active;});}
function reveal(target,scroll=true){for(const g of groups){const tab=g.tabs.find(t=>{const p=document.getElementById(t.dataset.target);return p===target||p.contains(target);});if(tab)activate(g,tab);}for(let n=target.parentElement;n;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;if(scroll)requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}
for(const g of groups){activate(g,g.tabs[0]);g.tabs.forEach((t,i)=>{t.addEventListener('click',()=>{activate(g,t);history.replaceState(null,'','#'+t.dataset.target);g.group.scrollIntoView({block:'start'});});t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%g.tabs.length;if(e.key==='ArrowLeft')n=(i+g.tabs.length-1)%g.tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=g.tabs.length-1;if(n!==undefined){e.preventDefault();activate(g,g.tabs[n]);g.tabs[n].focus();history.replaceState(null,'','#'+g.tabs[n].dataset.target);}});});}
function hash(){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}const t=document.getElementById(id);if(t)reveal(t);}hash();window.addEventListener('hashchange',hash);root.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const t=document.getElementById(a.hash.slice(1));if(t){e.preventDefault();history.pushState(null,'',a.hash);reveal(t);}});
for(const f of root.querySelectorAll('.mc-estimator')){function calc(){const a=f.elements.spend,b=f.elements.results;f.querySelector('output').textContent=a.validity.valid&&b.validity.valid?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(a.valueAsNumber/b.valueAsNumber)+' ₫ / kết quả phù hợp':'Nhập ngân sách từ 0 và số kết quả nguyên lớn hơn 0.';}f.addEventListener('input',calc);f.addEventListener('submit',e=>e.preventDefault());calc();}
for(const preview of root.querySelectorAll('.mp-preview')){preview.querySelectorAll('[data-preview]').forEach(button=>button.addEventListener('click',()=>{preview.querySelectorAll('[data-preview]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));preview.querySelectorAll('[data-preview-panel]').forEach(panel=>panel.hidden=panel.dataset.previewPanel!==button.dataset.preview);}));}
const audienceSelect=root.querySelector('[data-audience-select]');audienceSelect?.addEventListener('change',()=>root.querySelectorAll('[data-audience-case]').forEach(panel=>panel.hidden=panel.dataset.audienceCase!==audienceSelect.value));
